package com.itb.inf2dm.absencemanager.controller; import java.util.*; import org.springframework.web.bind.annotation.*; import org.springframework.beans.factory.annotation.*; import com.itb.inf2dm.absencemanager.services.TurmaAlunoService; import com.itb.inf2dm.absencemanager.model.entity.TurmaAluno; @RestController @RequestMapping("/api/turma-alunos") public class TurmaAlunoController{ @Autowired TurmaAlunoService s; @GetMapping public List<TurmaAluno> all(){return s.findAll();} @PostMapping public TurmaAluno create(@RequestBody TurmaAluno t){return s.create(t);} }